#include <iostream>
#include <string>
#include <utility>

class Motor {
public:
    explicit Motor(int caballos) : caballos_(caballos) {}

    std::string arrancar() const {
        return "Motor de " + std::to_string(caballos_) + " CV en marcha";
    }

private:
    int caballos_;
};

class Auto {
public:
    Auto(std::string marca, Motor motor)
        : marca_(std::move(marca)), motor_(std::move(motor)) {}

    std::string arrancar() const {
        return marca_ + ": " + motor_.arrancar();
    }

private:
    std::string marca_;
    Motor motor_;
};

int main() {
    Auto auto1{"Toyota", Motor{120}};
    std::cout << auto1.arrancar() << '\n';
    return 0;
}

