class LectorLista:
    def __init__(self, filas):
        self.filas = filas

    def leer(self):
        return list(self.filas)

class LimpiadorNulos:
    def __init__(self, valor):
        self.valor = valor

    def limpiar(self, filas):
        limpias = []
        for fila in filas:
            if fila["ventas"] is None:
                fila = dict(fila, ventas=self.valor)
            limpias.append(fila)
        return limpias

class Resumen:
    def __init__(self, campo):
        self.campo = campo

    def calcular(self, filas):
        total = sum(fila[self.campo] for fila in filas)
        return {self.campo: total, "filas": len(filas)}

class Informe:
    def __init__(self, fuente, limpiador, resumen):
        self.fuente = fuente
        self.limpiador = limpiador
        self.resumen = resumen

    def generar(self):
        filas = self.fuente.leer()
        filas = self.limpiador.limpiar(filas)
        return self.resumen.calcular(filas)

datos = [
    {"sede": "Lima", "ventas": 100},
    {"sede": "Lima", "ventas": None},
    {"sede": "Arequipa", "ventas": 80},
]
informe = Informe(LectorLista(datos), LimpiadorNulos(0), Resumen("ventas"))
print(informe.generar())

class Escalador:
    def __init__(self, factor):
        self.factor = factor

    def aplicar(self, valores):
        return [v * self.factor for v in valores]

class Pipeline:
    def __init__(self, pasos):
        self.pasos = pasos

    def ejecutar(self, datos):
        for paso in self.pasos:
            datos = paso.aplicar(datos)
        return datos

p = Pipeline([Escalador(2), Escalador(10)])
print(p.ejecutar([1, 2]))

