class CalculadoraIGV:
    def __init__(self, tasa):
        self.tasa = tasa

    def calcular(self, subtotal):
        return round(subtotal * (1 + self.tasa), 2)

class Carrito:
    def __init__(self, calculadora):
        self.calculadora = calculadora
        self.items = []

    def agregar(self, precio):
        self.items.append(precio)

    def subtotal(self):
        return sum(self.items)

    def total(self):
        return self.calculadora.calcular(self.subtotal())

class SinImpuesto:
    def calcular(self, subtotal):
        return subtotal

carrito = Carrito(CalculadoraIGV(0.18))
carrito.agregar(100)
carrito.agregar(50)
print(carrito.subtotal(), carrito.total())

carrito2 = Carrito(SinImpuesto())
carrito2.agregar(100)
print(carrito2.subtotal(), carrito2.total())

class FuenteLista:
    def __init__(self, lecturas):
        self.lecturas = lecturas

    def leer(self):
        return list(self.lecturas)

class ReglaUmbral:
    def __init__(self, limite):
        self.limite = limite

    def evaluar(self, valor):
        return valor > self.limite

class Notificador:
    def __init__(self):
        self.alertas = []

    def enviar(self, mensaje):
        self.alertas.append(mensaje)

class Monitor:
    def __init__(self, fuente, regla, notificador):
        self.fuente = fuente
        self.regla = regla
        self.notificador = notificador

    def revisar(self):
        for posicion, valor in enumerate(self.fuente.leer(), start=1):
            if self.regla.evaluar(valor):
                self.notificador.enviar(f"lectura {posicion}: {valor}")
        return self.notificador.alertas

monitor = Monitor(FuenteLista([20, 35, 31, 10]), ReglaUmbral(30), Notificador())
print(monitor.revisar())

